const j = $input.first().json;
let raw = String(typeof j === 'string' ? j : (j.video_url ?? j['YouTube URL'] ?? j.url ?? '')).trim();
if (!raw) {
  throw new Error('Please enter a YouTube URL.');
}
if (!/^https?:\/\//i.test(raw)) {
  raw = 'https://' + raw;
}
const match = raw.match(/^https?:\/\/([^\/?#]+)(?:[\/?#]|$)/i);
if (!match) {
  throw new Error('Enter a valid URL. Received: ' + raw);
}
const host = match[1].toLowerCase().replace(/^www\./, '');
if (!['youtube.com','m.youtube.com','youtu.be','youtube-nocookie.com'].includes(host) && !host.endsWith('.youtube.com')) {
  throw new Error('Only youtube.com and youtu.be URLs are accepted. Received: ' + raw);
}
const clipCount = Math.max(1, Math.min(5, Number(j.clip_count ?? j['Number of clips (1-5)'] ?? 3)));
const maxDuration = Math.max(15, Math.min(90, Number(j.max_duration ?? j['Maximum clip length in seconds'] ?? 45)));
const formatRaw = String(j.aspect_ratio ?? j.Format ?? 'Portrait 9:16');
return [{
  json: {
    video_url: raw,
    clip_count: Number.isFinite(clipCount) ? clipCount : 3,
    max_duration: Number.isFinite(maxDuration) ? maxDuration : 45,
    aspect_ratio: /landscape/i.test(formatRaw) ? 'landscape' : 'portrait'
  }
}];

const r = $input.first().json;
if (r.error) throw new Error(String(r.error));
if (!Array.isArray(r.clips) || r.clips.length === 0) {
  throw new Error('The clip service returned no clips. Check the service logs and whether the video has usable captions.');
}
return [{json:{
  status: 'completed',
  source_url: r.source_url,
  title: r.title,
  output_directory: r.output_directory,
  clips_created: r.clips.length,
  clips: r.clips,
  message: `Created ${r.clips.length} clip(s). Files are saved in the output directory.`
}}];
